```python
import fernledger


def account_balances(csv_text):
    """Return the balance of every account in a journal of 'date,account,amount' lines with a header."""
    ledger = fernledger.read_journal(csv_text, skip_header=True)
    return {
        account: ledger.balance([account])
        for account in ledger.accounts()
    }
```

```python
def spending_by_month(ledger):
    """Return the total of the negative amounts per month, as positive numbers."""
    outgoing = ledger.filter(lambda entry: entry[2] < 0)
    return {
        month: -total
        for month, total in outgoing.group_by("month").sum().items()
    }
```

