```python
import gridwell


def blur_tiles(heights):
    """Return the heights averaged over each cell and its eight neighbors,
    wrapping at the map edges and rounding to two decimal places.
    """
    rows = len(heights)
    cols = len(heights[0]) if rows else 0

    if not rows or not cols:
        return []

    wrapped = [
        [heights[r % rows][c % cols] for c in range(-1, cols + 1)]
        for r in range(-1, rows + 1)
    ]
    smoothed = gridwell.smooth(wrapped, radius=1)

    return [
        [round(smoothed[r + 1][c + 1], 2) for c in range(cols)]
        for r in range(rows)
    ]
```

