```python
import gridwell


def brightest_after_clipping(image, ceiling):
    """Clip the image to the range [0, ceiling] and return the (row, column) of the brightest pixel;
    ties go to the first one in reading order."""
    clipped = gridwell.clip(image, 0, ceiling)
    return max(
        ((row, column) for row in range(clipped.height) for column in range(clipped.width)),
        key=lambda index: (clipped[index[0], index[1]], -index[0], -index[1]),
    )
